import styled from '@emotion/styled';
import type { BigNumberOrientation } from 'components/BigNumber/types';
import { theme } from 'theme';

interface StyledNoDataContainerProps {
  $orientation?: BigNumberOrientation;
  $inline?: boolean;
}

export const StyledNoDataContainer = styled.div<StyledNoDataContainerProps>(
  ({ $orientation, $inline }) => ({
    width: '100%',
    display: 'flex',
    flexWrap: 'wrap',
    gap: theme.spacing['2'],
    justifyContent: 'center',
    alignItems: 'center',
    height: '100%',
    ...($orientation === 'vertical' && { flexDirection: 'row' }),
    ...($orientation === 'horizontal' && { flexDirection: 'column' }),
    ...($orientation === 'none' && { flexDirection: 'column' }),
    ...($inline && {
      flexDirection: 'row',
      flexWrap: 'nowrap',
    }),
  }),
);

export const StyledNoDataText = styled.p({
  margin: 0,
  fontSize: '14px',
  color: '#141414',
  fontFamily: theme.fonts.paragraph,
});
